#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    long long n = s.size();
    // ones[j]: prefixes (after each char) where letter j has odd count
    int parity[26] = {0};
    long long ones[26] = {0};
    for (char c : s) {
        parity[c - 'a'] ^= 1;
        for (int j = 0; j < 26; j++) ones[j] += parity[j];
    }
    long long odd = 0; // total odd-frequency letters over all substrings
    for (int j = 0; j < 26; j++) odd += ones[j] * (n + 1 - ones[j]);
    long long oddLengths = ((n + 2) / 2) * ((n + 1) / 2);
    cout << (odd - oddLengths) / 2 << "\n";
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long n = s.length();
        // ones[j]: prefixes (after each char) where letter j has odd count
        int[] parity = new int[26];
        long[] ones = new long[26];
        for (int i = 0; i < n; i++) {
            parity[s.charAt(i) - 'a'] ^= 1;
            for (int j = 0; j < 26; j++) ones[j] += parity[j];
        }
        long odd = 0; // total odd-frequency letters over all substrings
        for (int j = 0; j < 26; j++) odd += ones[j] * (n + 1 - ones[j]);
        long oddLengths = ((n + 2) / 2) * ((n + 1) / 2);
        System.out.println((odd - oddLengths) / 2);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

