	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	var s string
	fmt.Fscan(r, &s)
	n := int64(len(s))
	// ones[j]: prefixes (after each char) where letter j has odd count
	var parity [26]int64
	var ones [26]int64
	for i := 0; i < len(s); i++ {
		parity[s[i]-'a'] ^= 1
		for j := 0; j < 26; j++ {
			ones[j] += parity[j]
		}
	}
	var odd int64 // total odd-frequency letters over all substrings
	for j := 0; j < 26; j++ {
		odd += ones[j] * (n + 1 - ones[j])
	}
	oddLengths := ((n + 2) / 2) * ((n + 1) / 2)
	fmt.Println((odd - oddLengths) / 2)
}
